using Freelancer604.DragDoll;using Studio;using UnityEngine;using Codex.DragDollPlusHistory;
int checks=0,failures=0,nextKey=100;
void Check(bool value,string why){if(!value)throw new Exception(why);}
void Test(string name,Action action){checks++;NativeFk.FailOnce=false;Timeline.Timeline.isPlaying=false;try{action();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e);}}
GuideObject Guide(Transform parent){var g=new GuideObject{dicKey=nextKey++};g.transformTarget.parent=parent;g.changeAmount.SetPosition=p=>g.transformTarget.localPosition=p;Studio.Studio.Amounts[g.dicKey]=g.changeAmount;return g;}
DragDollSession Make(bool height=false,bool parent=false){var c=new OCIChar{HeightEffect=height};var s=new DragDollSession{Character=c,HeightReady=height};DragDollPlugin.Sessions[c]=s;c.fkCtrl.Owner=c;var externalParent=parent?new Transform{localPosition=new(3,2,1),localScale=new(2,1.5f,.8f),localRotation=Quaternion.Euler(new(0,25,15))}:null;c.guideObject=Guide(externalParent);var pelvisParent=c.guideObject.transformTarget;if(height){s.Height=Guide(pelvisParent);pelvisParent=s.Height.transformTarget;s.inputPositions[pelvisParent]=pelvisParent.localPosition;}c.finalIK.solver.rootNode=new Transform{parent=pelvisParent,localPosition=new(0,1,0)};s.inputPositions[c.finalIK.solver.rootNode]=c.finalIK.solver.rootNode.localPosition;for(int i=0;i<2;i++){var g=Guide(c.finalIK.solver.rootNode);var b=new OCIChar.BoneInfo{guideObject=g};c.listBones.Add(b);s.bones[g.dicKey]=b;s.pose.Input[g.dicKey]=Vector3.zero;s.pose.Solved[g.dicKey]=Vector3.zero;}c.listIKTarget.Add(new(){guideObject=Guide(c.guideObject.transformTarget)});return s;}
float Visible(DragDollSession s)=>s.Character.listBones[0].guideObject.changeAmount.rot.x;
void SetPose(DragDollSession s,float value,float pelvisY=1){var v=new Vector3(value,0,0);foreach(int k in s.bones.Keys){s.pose.Input[k]=v;s.pose.Solved[k]=v;s.bones[k].guideObject.changeAmount.rot=v;}s.Character.listIKTarget[0].guideObject.changeAmount.pos=new(value,0,0);s.Solver.rootNode.localPosition=new(0,pelvisY,0);NativeFk.Evaluate(s.Character.fkCtrl);}
DragDollSession.FkHistoryCommand Gesture(DragDollSession s,float value,float pelvisY=1){var before=new DragDollSession.FkHistoryState(s);var old=s.Character.listIKTarget[0].guideObject.changeAmount.pos.x;SetPose(s,value,pelvisY);var after=new DragDollSession.FkHistoryState(s);return new(s,new IkCommand(s.Character,old,value),before,after);}
void Close(DragDollSession s,bool mark=true){s.Commit();s.disposed=true;DragDollPlugin.Sessions.Remove(s.Character);}
Test("active original undo and redo unchanged",()=>{var s=Make();var cmd=Gesture(s,30);cmd.Undo();Check(Visible(s)==0,"active undo");cmd.Redo();Check(Visible(s)==30,"active redo");});
Test("inactive undo restores baked FK without enabling IK",()=>{var s=Make();var cmd=Gesture(s,30);Close(s);cmd.Undo();Check(Visible(s)==0,"inactive visible pose unchanged");Check(!s.Character.finalIK.enabled&&!s.Character.oiCharInfo.enableIK&&s.Character.fkCtrl.enabled,"mode changed");});
Test("two undo and two redo restore adjacent endpoints",()=>{var s=Make();var a=Gesture(s,20);var b=Gesture(s,40);Close(s);b.Undo();Check(Visible(s)==20,"first undo");a.Undo();Check(Visible(s)==0,"second undo");a.Redo();Check(Visible(s)==20,"first redo");b.Redo();Check(Visible(s)==40,"second redo");});
Test("canonical solved includes pending override",()=>{var s=Make();var before=new DragDollSession.FkHistoryState(s);SetPose(s,30);var key=s.bones.Keys.First();s.pose.Pending[key]=new(45,0,0);var after=new DragDollSession.FkHistoryState(s);var cmd=new DragDollSession.FkHistoryCommand(s,new IkCommand(s.Character,0,30),before,after);Close(s);cmd.Undo();Check(Visible(s)==0,"undo pending");cmd.Redo();Check(Visible(s)==45,"pending override lost");});
Test("root pelvis movement without height restored",()=>{var s=Make();var before=s.Solver.rootNode.position;var cmd=Gesture(s,25,2);var after=s.Solver.rootNode.position;Close(s);cmd.Undo();Check((s.Solver.rootNode.position-before).sqrMagnitude<1e-7&&Visible(s)==0,"pelvis before wrong");cmd.Redo();Check((s.Solver.rootNode.position-after).sqrMagnitude<1e-7&&Visible(s)==25,"pelvis after wrong");});
Test("rotated scaled parent with height restore",()=>{var s=Make(true,true);var before=s.Solver.rootNode.position;var cmd=Gesture(s,15,2);var after=s.Solver.rootNode.position;Close(s);cmd.Undo();Check((s.Solver.rootNode.position-before).sqrMagnitude<1e-6&&Visible(s)==0,"height before wrong");cmd.Redo();Check((s.Solver.rootNode.position-after).sqrMagnitude<1e-6&&Visible(s)==15,"height after wrong");});
Test("external FK modification preserved",()=>{var s=Make();var cmd=Gesture(s,30);Close(s);s.Character.listBones[0].guideObject.changeAmount.rot=new(77,0,0);cmd.Undo();Check(Visible(s)==77,"foreign FK overwritten");});
Test("replacement character controller rejects history",()=>{var s=Make();var cmd=Gesture(s,30);Close(s);s.Character.charInfo=new();cmd.Undo();Check(Visible(s)==30,"replacement mutated");});
Test("replacement clothing coordinate rejects history",()=>{var s=Make();var cmd=Gesture(s,30);Close(s);s.Character.charInfo.nowCoordinate=new();cmd.Undo();Check(Visible(s)==30,"coordinate replacement mutated");});
Test("removed live bone rejects history",()=>{var s=Make();var cmd=Gesture(s,30);Close(s);s.Character.listBones.RemoveAt(1);cmd.Undo();Check(Visible(s)==30,"removed bone modified");});
Test("new session retires old inactive lease",()=>{var s=Make();var cmd=Gesture(s,30);Close(s);DragDollPlugin.Sessions[s.Character]=new(){Character=s.Character};cmd.Undo();Check(Visible(s)==30,"old history entered new session");});
Test("mode change to IK refuses inactive apply",()=>{var s=Make();var cmd=Gesture(s,30);Close(s);s.Character.finalIK.enabled=true;s.Character.oiCharInfo.enableIK=true;cmd.Undo();Check(Visible(s)==30,"new IK mode overwritten");});
Test("moving root parent refuses stale world pose",()=>{var s=Make(false,true);var cmd=Gesture(s,30);Close(s);s.Character.guideObject.transformTarget.parent.localPosition+=new Vector3(1,0,0);cmd.Undo();Check(Visible(s)==30,"parent edit overwritten");});
Test("one setter failure rolls back already written values",()=>{var s=Make();var cmd=Gesture(s,30);Close(s);s.Character.listBones[1].guideObject.changeAmount.FailRotationOnce=true;cmd.Undo();Check(Visible(s)==30&&s.Character.listBones[1].guideObject.changeAmount.rot.x==30,"partial write remains");});
Test("native FK failure restores old stable values",()=>{var s=Make();var cmd=Gesture(s,30);Close(s);NativeFk.FailOnce=true;cmd.Undo();Check(Visible(s)==30,"native failure left halfpose");});
Test("two actors own independent inactive leases",()=>{var a=Make();var ac=Gesture(a,10);var b=Make();var bc=Gesture(b,50);Close(a);Close(b);ac.Undo();Check(Visible(a)==0&&Visible(b)==50,"actors crossed");bc.Undo();Check(Visible(b)==0,"second actor undo");});
Test("Timeline playback refuses without changing IK or FK",()=>{var s=Make();var cmd=Gesture(s,30);Close(s);Timeline.Timeline.isPlaying=true;cmd.Undo();Check(Visible(s)==30&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==30,"timeline state overwritten");});
Test("captured Timeline ownership refuses stale history",()=>{var s=Make();s.timelineTracks[1]=()=>true;var cmd=Gesture(s,30);Close(s);cmd.Undo();Check(Visible(s)==30&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==30,"track history overwritten");});
Test("failed original Commit does not authorize inactive FK restore",()=>{var s=Make();var cmd=Gesture(s,30);s.FailBake=true;bool threw=false;try{s.Commit();}catch{threw=true;}s.disposed=true;DragDollPlugin.Sessions.Remove(s.Character);cmd.Undo();Check(threw&&Visible(s)==30,"failed commit authored inactive pose");});
Test("original Commit still performs one bake and turns IK off",()=>{var s=Make();Gesture(s,30);Close(s);Check(s.BakeCalls==1&&!s.Character.finalIK.enabled&&!s.Character.oiCharInfo.enableIK&&s.Character.fkCtrl.enabled&&s.Character.oiCharInfo.enableFK,"original close mode changed");});
Test("destroyed height guide refuses whole history",()=>{var s=Make(true);var cmd=Gesture(s,20,2);Close(s);s.Height.Destroyed=true;cmd.Undo();Check(Visible(s)==20&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==20,"destroyed height touched");});
Test("destroyed root parent does not alias actual null",()=>{var s=Make(false,true);var cmd=Gesture(s,20);Close(s);s.Character.guideObject.transformTarget.parent.Destroyed=true;s.Character.guideObject.transformTarget.parent=null;cmd.Undo();Check(Visible(s)==20&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==20,"destroyed parent admitted");});
Test("canonical history ignores extra visible rotation correction",()=>{var s=Make();var before=new DragDollSession.FkHistoryState(s);SetPose(s,25);foreach(var b in s.Character.listBones)b.guideObject.transformTarget.localEulerAngles=new(55,0,0);var after=new DragDollSession.FkHistoryState(s);var cmd=new DragDollSession.FkHistoryCommand(s,new IkCommand(s.Character,0,25),before,after);Close(s);cmd.Undo();Check(Visible(s)==0,"uncorrected undo");cmd.Redo();Check(Visible(s)==25,"extra visual correction baked twice");});
Test("captured hand shape follows history endpoints",()=>{var s=Make();var before=new DragDollSession.FkHistoryState(s,true);SetPose(s,20);s.Character.charInfo.Hands[0]=2;var after=new DragDollSession.FkHistoryState(s,true);var cmd=new DragDollSession.FkHistoryCommand(s,new IkCommand(s.Character,0,20),before,after);Close(s);cmd.Undo();Check(Visible(s)==0&&s.Character.charInfo.Hands[0]==0,"hand before lost");cmd.Redo();Check(Visible(s)==20&&s.Character.charInfo.Hands[0]==2,"hand redo lost");});
Test("hand restore failure path rolls back with FK",()=>{var s=Make();var before=new DragDollSession.FkHistoryState(s,true);SetPose(s,20);s.Character.charInfo.Hands[0]=2;var after=new DragDollSession.FkHistoryState(s,true);var cmd=new DragDollSession.FkHistoryCommand(s,new IkCommand(s.Character,0,20),before,after);Close(s);NativeFk.FailOnce=true;cmd.Undo();Check(Visible(s)==20&&s.Character.charInfo.Hands[0]==2,"hand partial restore leaked");});
Test("external hand change rejects inactive command",()=>{var s=Make();var cmd=Gesture(s,20);Close(s);s.Character.charInfo.Hands[0]=7;cmd.Undo();Check(Visible(s)==20&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==20&&s.Character.charInfo.Hands[0]==7,"external hands touched");});
Test("external input position edit rejects inactive command",()=>{var s=Make();var cmd=Gesture(s,20);Close(s);s.Solver.rootNode.localPosition+=new Vector3(.5f,0,0);cmd.Undo();Check(Visible(s)==20&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==20,"external position touched");});
Test("non-solved capture preserves canonical input",()=>{var s=Make();s.capturedSolve=false;var before=new DragDollSession.FkHistoryState(s);SetPose(s,20);foreach(var k in s.bones.Keys)s.pose.Solved[k]=new(88,0,0);var after=new DragDollSession.FkHistoryState(s);var cmd=new DragDollSession.FkHistoryCommand(s,new IkCommand(s.Character,0,20),before,after);Close(s);cmd.Undo();Check(Visible(s)==0,"input undo failed");cmd.Redo();Check(Visible(s)==20,"unused solved snapshot overwritten input");});
Test("post-gesture pre-close root edit blocks whole stale endpoint",()=>{var s=Make();var cmd=Gesture(s,20);s.Character.guideObject.changeAmount.pos=new(4,0,0);Close(s);var root=s.Character.guideObject.changeAmount.pos;cmd.Undo();Check(Visible(s)==20&&s.Character.guideObject.changeAmount.pos==root&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==20,"extra root edit overwritten");});
Test("post-gesture pre-close height edit blocks stale endpoint",()=>{var s=Make(true);var cmd=Gesture(s,20);s.Height.changeAmount.pos=new(0,4,0);Close(s);var height=s.Height.changeAmount.pos;cmd.Undo();Check(Visible(s)==20&&s.Height.changeAmount.pos==height&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==20,"extra height edit overwritten");});
Test("post-gesture pre-close hand edit blocks stale endpoint",()=>{var s=Make();var cmd=Gesture(s,20);s.Character.charInfo.Hands[0]=5;Close(s);cmd.Undo();Check(Visible(s)==20&&s.Character.charInfo.Hands[0]==5&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==20,"extra hand edit overwritten");});
Test("post-close native root scale edit rejects old history",()=>{var s=Make();var cmd=Gesture(s,20);Close(s);s.Character.guideObject.changeAmount.scale=new(2,2,2);s.Character.guideObject.transformTarget.localScale=new(2,2,2);var root=s.Character.guideObject.changeAmount.pos;cmd.Undo();Check(Visible(s)==20&&s.Character.guideObject.changeAmount.pos==root&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==20,"scaled rig restored stale world pose");});
Test("post-close height effect disable rejects old height writes",()=>{var s=Make(true);var cmd=Gesture(s,20,2);Close(s);s.Character.HeightEffect=false;var h=s.Height.changeAmount.pos;cmd.Undo();Check(Visible(s)==20&&s.Height.changeAmount.pos==h&&s.Character.listIKTarget[0].guideObject.changeAmount.pos.x==20,"disabled height effect written");});
Console.WriteLine($"checks={checks} failures={failures}");return failures==0?0:1;
sealed class IkCommand:Studio.ICommand{readonly OCIChar character;readonly float before,after;public IkCommand(OCIChar c,float b,float a){character=c;before=b;after=a;}public void Do()=>Redo();public void Undo()=>character.listIKTarget[0].guideObject.changeAmount.pos=new(before,0,0);public void Redo()=>character.listIKTarget[0].guideObject.changeAmount.pos=new(after,0,0);}
